<?php
declare(strict_types=1); require_once __DIR__.DIRECTORY_SEPARATOR.'auth.php'; session_start_secure(); send_security_headers(); header('Content-Type: text/html; charset=utf-8'); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){ if(!csrf_is_valid($_POST['csrf_token']??null)){$error='The form expired. Please try again.';} else { $u=is_string($_POST['username']??null)?trim($_POST['username']):''; $p=is_string($_POST['password']??null)?$_POST['password']:''; if($u!==''&&$p!==''&&strlen($u)<=50){try{$q=db_connection()->prepare('SELECT id,password_hash FROM admins WHERE username=? LIMIT 1');$q->execute([$u]);$a=$q->fetch();if(is_array($a)&&password_verify($p,(string)$a['password_hash'])){session_regenerate_id(true);$_SESSION['admin_id']=(int)$a['id'];csrf_rotate();header('Location: index.php');exit;}}catch(Throwable $e){error_log('Administrator login failed: '.get_class($e));}} $error='Invalid username or password.';}}
echo '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Administrator login</title></head><body><h1>Administrator login</h1>'; if($error!=='')echo '<p role="alert">'.admin_e($error).'</p>'; echo '<form method="post"><input type="hidden" name="csrf_token" value="'.admin_e(csrf_token()).'"><p><label>Username <input name="username" maxlength="50" required autocomplete="username"></label></p><p><label>Password <input type="password" name="password" required autocomplete="current-password"></label></p><button>Sign in</button></form></body></html>';
